create or replace view public.operation_cost_summary with (security_invoker=true) as select o.tenant_id,o.id operation_id,coalesce(sum(q.amount_minor) filter(where q.status in ('selected','contracted')),0)::bigint selected_cost_minor,coalesce(sum(q.amount_minor) filter(where q.status in ('quoted','shortlisted')),0)::bigint pipeline_quote_minor,count(*) filter(where q.status in ('selected','contracted'))::int selected_quotes,count(q.id)::int total_quotes from public.operations o left join public.operation_quotes q on q.operation_id=o.id and q.tenant_id=o.tenant_id group by o.tenant_id,o.id; grant select on public.operation_cost_summary to authenticated;